const $=(e,t)=>({value:e,label:t});export const CURRENCY_SETS=Object.freeze({USD:Object.freeze({symbol:"$",name:"USD",places:2,units:Object.freeze([$(1e4,"$100"),$(5e3,"$50"),$(2e3,"$20"),$(1e3,"$10"),$(500,"$5"),$(200,"$2"),$(100,"$1"),$(25,"Quarter"),$(10,"Dime"),$(5,"Nickel"),$(1,"Penny")]),minCoin:10}),EUR:Object.freeze({symbol:"€",name:"EUR",places:2,units:Object.freeze([$(5e4,"€500"),$(2e4,"€200"),$(1e4,"€100"),$(5e3,"€50"),$(2e3,"€20"),$(1e3,"€10"),$(500,"€5"),$(200,"€2"),$(100,"€1"),$(50,"50c"),$(20,"20c"),$(10,"10c"),$(5,"5c"),$(2,"2c"),$(1,"1c")]),minCoin:10}),JPY:Object.freeze({symbol:"¥",name:"JPY",places:0,units:Object.freeze([$(1e4,"¥10000"),$(5e3,"¥5000"),$(2e3,"¥2000"),$(1e3,"¥1000"),$(500,"¥500"),$(100,"¥100"),$(50,"¥50"),$(10,"¥10"),$(5,"¥5"),$(1,"¥1")]),minCoin:1}),CNY:Object.freeze({symbol:"¥",name:"CNY",places:1,units:Object.freeze([$(1e3,"¥100"),$(500,"¥50"),$(200,"¥20"),$(100,"¥10"),$(50,"¥5"),$(10,"¥1"),$(5,"5jiao"),$(1,"1jiao")]),minCoin:1})});export function getCurrency(e){return CURRENCY_SETS[e]||CURRENCY_SETS.USD}export function toCents(e,t="USD"){const n=getCurrency(t).places;return Math.round(e*Math.pow(10,n))}export function fromCents(e,t="USD"){const n=getCurrency(t).places;return+(e/Math.pow(10,n)).toFixed(n)}export function parseInput(e){if(!e||"string"!=typeof e)return null;const t=e.trim();let n;if(t.includes(" "))n=t.split(/\s+/);else if(t.includes("/"))n=t.split("/");else if(t.includes("+"))n=t.split("+");else{if(!t.includes(","))return null;n=t.split(",")}if(n.length<2)return null;const a=parseFloat(n[0]),r=parseFloat(n[1]);return isNaN(a)||isNaN(r)||a<0||r<0?null:{price:Math.round(100*a)/100,paid:Math.round(100*r)/100}}export function greedy(e,t=CURRENCY_SETS.USD.units,n=1/0){let a=e;const r=[];for(const e of t){if(a<e.value)continue;const t=Math.min(Math.floor(a/e.value),n);if(t>0&&(r.push({value:e.value,label:e.label,count:t}),a-=e.value*t),0===a)break}return{items:r,remaining:a}}const DESCRIPTIONS={optimal:"Uses the fewest pieces possible. Best for fast cash transactions.",balanced:"Spreads change across more denominations. Great for everyday wallet use.",practical:"Avoids tiny coins. Ideal when the receiver prefers fewer small coins."};export function calculate(e,t,n="USD"){const a=getCurrency(n),r=toCents(e,n),s=toCents(t,n);if(isNaN(r)||isNaN(s)||r<0||s<0)return{status:"invalid",balance:0,plans:[],currency:n};const i=s-r;if(0===i)return{status:"exact",balance:0,plans:[],currency:n};if(i<0)return{status:"short",balance:fromCents(i,n),plans:[],currency:n};const l=[{id:"optimal",name:"Optimal Plan",cap:1/0,filter:null},{id:"balanced",name:"Balanced Plan",cap:3,filter:null},{id:"practical",name:"Practical Plan",cap:1/0,filter:e=>e.value>=a.minCoin}].map(e=>{const t=e.filter?a.units.filter(e.filter):a.units;let r=greedy(i,t,e.cap);"practical"===e.id&&r.remaining>0&&(r=greedy(i,a.units));const s=r.items.map(e=>({value:fromCents(e.value,n),label:e.label,count:e.count}));return{id:e.id,name:e.name,totalCount:r.items.reduce((e,t)=>e+t.count,0),typeCount:r.items.length,units:s,desc:DESCRIPTIONS[e.id]}});return{status:"settled",balance:fromCents(i,n),plans:l,currency:n}}